    public static int pkParseEngines(byte[] b, int from, int to, emon.Port.Cells out, StringBuilder msg) {
        // Read a comma-separated list of engine names (`tesseract,ppocr`, spaces around a name allowed; an option's value) and push their ids to `out`. 0, or `pkerr-unknown-engine` with the name in `msg`.
        int s = from;
        int i = from;
        int c = 44;
        int a = 0;
        int z = 0;
        int code = 0;
        while (i <= to) {
            c = 44;
            if (i < to) {
                c = emon.Port.blobU8(b, i);
            }
            if (c == 44) {
                a = s;
                z = i;
                while ((a < z) && (emon.Port.blobU8(b, a) == 32)) {
                    a += 1;
                }
                while ((a < z) && (emon.Port.blobU8(b, z - 1) == 32)) {
                    z -= 1;
                }
                if (z > a) {
                    code = engFind(b, a, z);
                    if (code < 0) {
                        return pkNameMsg(msg, pkerrUnknownEngine(), b, a, z);
                    }
                    emon.Port.cellsPush(out, code);
                }
                s = i + 1;
            }
            i += 1;
        }
        return 0;
    }
